programa
{
    funcao inicio()
    {
        inteiro valor, n, i, indice
        inteiro numeros[20]

        escreva("Valor procurado: ")
        leia(valor)
        escreva("Quantos numeros? ")
        leia(n)

        para (i = 0; i < n; i++)
        {
            leia(numeros[i])
        }

        indice = -1
        para (i = n - 1; i > -1; i--)
        {
            se (numeros[i] == valor)
            {
                indice = i
                pare
            }
        }

        escreva("Ultimo indice: ", indice, "\n")
    }
}
